const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const env = typeof $env === 'object' && $env ? $env : {};
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const publicImageUrl = String(env.MVP_SIMPLE_POST_IMAGE_URL || '').trim();
const usePublicJpeg = /^https?:\/\//i.test(publicImageUrl) && /\.jpe?g(?:[?#].*)?$/i.test(publicImageUrl);
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Post Asset Item did not produce a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Post Asset Item did not produce a title.');
}
return [{
  json: {
    content_id: contentId,
    title,
    current_status: String($json.status ?? 'script_complete'),
    caption_final: String($json.caption_final ?? ''),
    hashtags_final: String($json.hashtags_final ?? ''),
    asset_role: 'post_image',
    provider: usePublicJpeg ? 'public_image_url' : 'repo_static_asset',
    source_url: usePublicJpeg ? publicImageUrl : '/workflows/assets/mvp_simple_post.svg',
    storage_url: usePublicJpeg ? publicImageUrl : '/workflows/assets/mvp_simple_post.svg',
    mime_type: usePublicJpeg ? 'image/jpeg' : 'image/svg+xml',
    width: 1080,
    height: 1080,
    status_after_asset: 'assets_ready',
    asset_validation_note: usePublicJpeg
      ? 'Using MVP_SIMPLE_POST_IMAGE_URL as the public JPEG source for Instagram publish testing.'
      : 'Using the repo-local SVG fallback. This is valid for local asset smoke tests but not for Instagram API publishing.'
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare Asset SQL Values received an invalid content_id: ${contentId || '<empty>'}.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    asset_role_sql: String($json.asset_role ?? 'post_image').replaceAll("'", "''"),
    provider_sql: String($json.provider ?? 'repo_static_asset').replaceAll("'", "''"),
    source_url_sql: String($json.source_url ?? '').replaceAll("'", "''"),
    storage_url_sql: String($json.storage_url ?? '').replaceAll("'", "''"),
    mime_type_sql: String($json.mime_type ?? 'image/svg+xml').replaceAll("'", "''"),
    status_sql: 'ready'
  }
}];
